input.old_string:
# Prepare JSON payload
CONFIG_JSON=$(awk -F'=' '{
    if ($0 !~ /^#/ && $0 !~ /^$/) {
        gsub(/\\"/, "\\\\\"", $2);  # Escape quotes
        gsub(/\\n/, "\\\\n", $2);    # Escape newlines
        printf "\"%s\":\"%s\","", $1, $2
    }
}' ".env.test" | sed 's/,$//')  # Remove trailing comma

CONFIG_JSON="{${CONFIG_JSON}}"

input.new_string:
# Prepare JSON payload
CONFIG_JSON=$(awk -F'=' 'BEGIN {
    printf "{"
}
!/^#/ && !/^$/ {
    gsub(/"/, "\\\"", $2);  # Escape quotes
    gsub(/\n/, "\\n", $2);    # Escape newlines
    printf "\"%s\":\"%s\","", $1, $2
}
END {
    printf "}"
}' ".env.test" | sed 's/,}/}/')  # Remove trailing comma before closing brace

